// A wet well that fills from the sewer and is pumped down by the duty pump.
const s = context.get("s") || { level: 45, duty: "P-101", running: false, n: 0 };
const inflow = 1.1 + 0.4 * Math.sin(s.n / 15);        // % per second
s.n += 1;
if (!s.running && s.level >= 70) s.running = true;
if (s.running && s.level <= 30) { s.running = false; s.duty = s.duty === "P-101" ? "P-102" : "P-101"; }
s.level = Math.max(0, Math.min(100, s.level + inflow - (s.running ? 2.6 : 0)));
context.set("s", s);
const flow = s.running ? 82 + Math.random() * 6 : 0;
msg.payload = {
    "LIT-101": Number(s.level.toFixed(1)),
    "FIT-101": Number(flow.toFixed(1)),
    "PIT-101": Number((s.running ? 2.4 + Math.random() * 0.2 : 0.3).toFixed(2)),
    "P-101": s.running && s.duty === "P-101",
    "P-102": s.running && s.duty === "P-102",
    "Discharge": s.running,
    "Inlet": true,
    "LSH-101": s.level > 90 ? "alarm" : "ok",
    "WW-101": s.level > 90 ? "alarm" : "ok"
};
return msg;
